#include <stdio.h>
#include <stdlib.h>

#define MAX_N 200000

int main() {
    int n;
    scanf("%d", &n);

    int weights[MAX_N];
    long long total_weight = 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &weights[i]);
        total_weight += weights[i];
    }

    // dp[i] = minimal last value of an increasing subsequence of length i+1
    // We'll store indices of weights to compare values.
    // Since weights are distinct, we can do LIS in O(n log n)

    int lis_len = 0;
    int tails[MAX_N]; // stores minimal last weight for LIS of given length

    for (int i = 0; i < n; i++) {
        int w = weights[i];

        // binary search for the first tail >= w
        int left = 0, right = lis_len;
        while (left < right) {
            int mid = (left + right) / 2;
            if (tails[mid] < w)
                left = mid + 1;
            else
                right = mid;
        }
        tails[left] = w;
        if (left == lis_len)
            lis_len++;
    }

    // Now we need sum of weights in LIS — but tails stores only last values, not the actual sum.
    // So we need another approach: reconstruct LIS to know which weights are in it.
    // Let's do standard LIS reconstruction with predecessor.

    int prev_index[MAX_N];
    int lis_pos[MAX_N]; // position in lis sequence for each element index
    int lis_indices[MAX_N]; // stores indices forming the LIS

    for (int i = 0; i < n; i++) {
        int w = weights[i];

        int left = 0, right = lis_len;
        while (left < right) {
            int mid = (left + right) / 2;
            if (weights[lis_indices[mid]] < w)
                left = mid + 1;
            else
                right = mid;
        }

        lis_pos[i] = left;
        lis_indices[left] = i;

        if (left > 0)
            prev_index[i] = lis_indices[left - 1];
        else
            prev_index[i] = -1;

        if (left == lis_len)
            lis_len++;
    }

    // Reconstruct LIS
    int *in_lis = calloc(n, sizeof(int));
    int idx = lis_indices[lis_len - 1];
    while (idx != -1) {
        in_lis[idx] = 1;
        idx = prev_index[idx];
    }

    long long lis_sum = 0;
    for (int i = 0; i < n; i++) {
        if (in_lis[i])
            lis_sum += weights[i];
    }

    long long answer = total_weight - lis_sum;
    printf("%lld\n", answer);

    free(in_lis);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        int w[1000];
        for (int i = 0; i < n; i++) scanf("%d", &w[i]);

        // Create sorted version to find target positions
        int sorted[1000];
        for (int i = 0; i < n; i++) sorted[i] = w[i];
        qsort(sorted, n, sizeof(int), cmp);

        int global_min = sorted[0];

        // Map each value to its target index
        // Since all weights are distinct, we can map value -> sorted position
        // visited array
        int visited[1000] = {0};

        // For each element, find where it needs to go
        // w[i] should go to position where sorted[pos] == w[i]
        // Create pos_of[value] but values can be large, use a different approach
        // Create mapping: for each i, target[i] = position in sorted array of w[i]
        int target[1000];
        for (int i = 0; i < n; i++) {
            // binary search for w[i] in sorted
            int lo = 0, hi = n-1;
            while (lo < hi) {
                int mid = (lo+hi)/2;
                if (sorted[mid] < w[i]) lo = mid+1;
                else hi = mid;
            }
            target[i] = lo;
        }

        long long total = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] || target[i] == i) { visited[i] = 1; continue; }
            // find cycle
            int cycle_len = 0;
            long long cycle_sum = 0;
            int cycle_min = 1e9;
            int j = i;
            while (!visited[j]) {
                visited[j] = 1;
                cycle_len++;
                cycle_sum += w[j];
                if (w[j] < cycle_min) cycle_min = w[j];
                j = target[j];
            }
            long long cost1 = cycle_sum + (long long)(cycle_len-2)*cycle_min;
            long long cost2 = cycle_sum + cycle_min + (long long)(cycle_len+1)*global_min;
            total += (cost1 < cost2) ? cost1 : cost2;
        }
        printf("%lld\n", total);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int w;
    int idx;
} Item;

int cmp_item(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;
    if (x->w < y->w) return -1;
    if (x->w > y->w) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *a = (int *)malloc(sizeof(int) * n);
    Item *b = (Item *)malloc(sizeof(Item) * n);
    int *to = (int *)malloc(sizeof(int) * n);
    int *vis = (int *)calloc(n, sizeof(int));

    ll global_min = (1LL << 60);

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        b[i].w = a[i];
        b[i].idx = i;
        if (a[i] < global_min) global_min = a[i];
    }

    qsort(b, n, sizeof(Item), cmp_item);

    for (int i = 0; i < n; i++) {
        to[b[i].idx] = i;
    }

    ll ans = 0;

    for (int i = 0; i < n; i++) {
        if (vis[i]) continue;

        int cur = i;
        ll sum = 0;
        ll cycle_min = (1LL << 60);
        int cnt = 0;

        while (!vis[cur]) {
            vis[cur] = 1;
            ll w = a[cur];
            sum += w;
            if (w < cycle_min) cycle_min = w;
            cnt++;
            cur = to[cur];
        }

        if (cnt <= 1) continue;

        ll method1 = sum + (ll)(cnt - 2) * cycle_min;
        ll method2 = sum + cycle_min + (ll)(cnt + 1) * global_min;

        ans += (method1 < method2) ? method1 : method2;
    }

    printf("%lld\n", ans);

    free(a);
    free(b);
    free(to);
    free(vis);

    return 0;
}

