int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> w(n);
    long long total_weight = 0;
    for (int i = 0; i < n; i++) {
        cin >> w[i];
        total_weight += w[i];
    }

    // Find LIS length, but we need sum of weights in LIS, so we store sums not lengths
    // Use patience sorting: for each weight, replace first element >= weight in tails
    // But here we need max sum increasing subsequence (MSIS)

    // DP approach O(n^2) is fine for n up to maybe 2000; if n up to 2e5 we need Fenwick tree.
    // Since constraints not given, we implement O(n log n) using BIT for max sum.

    // Coordinate compress weights
    vector<int> comp = w;
    sort(comp.begin(), comp.end());
    comp.erase(unique(comp.begin(), comp.end()), comp.end());
    int m = comp.size();

    // Fenwick tree for maximum sum
    vector<long long> bit(m + 2, 0);

    auto update = [&](int idx, long long val) {
        idx++;
        while (idx <= m) {
            bit[idx] = max(bit[idx], val);
            idx += idx & -idx;
        }
    };

    auto query = [&](int idx) {
        idx++;
        long long res = 0;
        while (idx > 0) {
            res = max(res, bit[idx]);
            idx -= idx & -idx;
        }
        return res;
    };

    long long max_sum = 0;
    for (int weight : w) {
        int pos = lower_bound(comp.begin(), comp.end(), weight) - comp.begin();
        long long best = query(pos - 1) + weight;
        update(pos, best);
        max_sum = max(max_sum, best);
    }

    cout << total_weight - max_sum << "\n";

    return 0;
}

