int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    while (cin >> n && n != 0) {
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        // Sort to find target positions
        vector<int> sorted_a = a;
        sort(sorted_a.begin(), sorted_a.end());

        // Map value to target index
        map<int, int> pos;
        for (int i = 0; i < n; i++) pos[sorted_a[i]] = i;

        // Build permutation: where does element at position i need to go?
        // a[i] needs to go to pos[a[i]]
        vector<int> perm(n);
        for (int i = 0; i < n; i++) perm[i] = pos[a[i]];

        int global_min = sorted_a[0];

        vector<bool> visited(n, false);
        long long total_effort = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i] || perm[i] == i) {
                visited[i] = true;
                continue;
            }

            // Find cycle
            vector<int> cycle;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                cycle.push_back(j);
                j = perm[j];
            }

            if (cycle.size() == 1) continue;

            long long s = 0;
            int m = INT_MAX;
            for (int idx : cycle) {
                s += a[idx];
                m = min(m, a[idx]);
            }

            int len = cycle.size();
            long long opt1 = s + (long long)(len - 2) * m;
            long long opt2 = s + m + (long long)(len + 1) * global_min;

            total_effort += min(opt1, opt2);
        }

        cout << total_effort << "\n";
    }

    return 0;
}

