public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] weights = new int[n];
        int[] sorted = new int[n];

        for (int i = 0; i < n; i++) {
            weights[i] = sc.nextInt();
            sorted[i] = weights[i];
        }

        Arrays.sort(sorted);

        // Find longest prefix of sorted that appears as subsequence in original
        int j = 0;
        for (int i = 0; i < n && j < n; i++) {
            if (weights[i] == sorted[j]) {
                j++;
            }
        }

        // j is the number of items already in correct relative order
        // These items do not need to be moved
        long totalWeight = 0;
        for (int w : weights) {
            totalWeight += w;
        }

        long keptWeight = 0;
        for (int i = 0; i < j; i++) {
            keptWeight += sorted[i];
        }

        long minEffort = totalWeight - keptWeight;
        System.out.println(minEffort);
    }
}

