public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            int[] w = new int[n];
            for (int i = 0; i < n; i++) w[i] = sc.nextInt();

            int[] sorted = w.clone();
            Arrays.sort(sorted);
            Map<Integer, Integer> pos = new HashMap<>();
            for (int i = 0; i < n; i++) pos.put(sorted[i], i);

            int[] perm = new int[n];
            for (int i = 0; i < n; i++) perm[i] = pos.get(w[i]);

            boolean[] visited = new boolean[n];
            int globalMin = sorted[0];
            long totalCost = 0;

            for (int i = 0; i < n; i++) {
                if (visited[i] || perm[i] == i) { visited[i] = true; continue; }
                List<Integer> cycle = new ArrayList<>();
                int j = i;
                while (!visited[j]) { visited[j] = true; cycle.add(sorted[j]); j = perm[j]; }
                int k = cycle.size();
                long sum = 0; int minC = Integer.MAX_VALUE;
                for (int x : cycle) { sum += x; minC = Math.min(minC, x); }
                long opt1 = sum + (long)minC * (k - 2);
                long opt2 = sum + minC + (long)globalMin * (k + 1);
                totalCost += Math.min(opt1, opt2);
            }
            System.out.println(totalCost);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        int[] a = new int[n];
        int[] sorted = new int[n];

        int globalMin = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            sorted[i] = a[i];
            globalMin = Math.min(globalMin, a[i]);
        }

        Arrays.sort(sorted);

        Map<Integer, Integer> posInSorted = new HashMap<>();
        for (int i = 0; i < n; i++) {
            posInSorted.put(sorted[i], i);
        }

        int[] to = new int[n];
        for (int i = 0; i < n; i++) {
            to[i] = posInSorted.get(a[i]);
        }

        boolean[] visited = new boolean[n];
        long answer = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;

            int cur = i;
            int cycleSize = 0;
            long cycleSum = 0;
            int cycleMin = Integer.MAX_VALUE;

            while (!visited[cur]) {
                visited[cur] = true;
                int w = a[cur];
                cycleSize++;
                cycleSum += w;
                cycleMin = Math.min(cycleMin, w);
                cur = to[cur];
            }

            if (cycleSize <= 1) continue;

            long method1 = cycleSum + (long) (cycleSize - 2) * cycleMin;
            long method2 = cycleSum + cycleMin + (long) (cycleSize + 1) * globalMin;

            answer += Math.min(method1, method2);
        }

        System.out.println(answer);
    }
